    def get_id_for_current(self, class_name, timeout=10, alias="default"):
        """Get id for current item.

        :param string class_name: SMOD, BTS, LNBTS, WNBTS or GNBTS
        :param float timeout: Time to wait for positive procedure result.
        :param string alias: Name of execution context.

        :rtype: string
        :return: distname to the connected entity id
        """
        timeout = timestr_to_secs(timeout)
        IsOneOf("SMOD", "BTS", "LNBTS", "WNBTS", "GNBTS", "NRBTS", "RMOD", "ASIRMOD").check(class_name)

        return self.store.get(alias).execute_infomodel_request("getConnectedEntityId", {"entityType": class_name}, timeout)

    def get_smod_position(self, timeout=10, alias="default"):
        """Get SMOD posistion.

        :param float timeout: Time to wait for positive procedure result.
        :param string alias: Name of execution context.

        :rtype: string
        :return: SMOD position
        """
        timeout = timestr_to_secs(timeout)
        reply = self.store.get(alias).execute_infomodel_request(
            "getSmodPosition", {}, timeout)
        if isinstance(reply, dict):
            smod = [reply[s][0] for s in reply]
            for item in smod:
                if _search_recursively(item, "activeRole") == "primary":
                    get_val = _search_recursively(item, "positionOnShelf")
                    break
                else:
                    get_val = _search_recursively(reply, "positionOnShelf")
            result = get_val.split("Side")[0] if get_val.startswith(
                "left") or get_val.startswith("right") else get_val
            return result
        else:
            return reply

