    def assert_alarm_active(self, parameters=None, timeout=60, alias="default"):
        """Assert that there is any active alarm matching given parameters.

        :param string parameters: Requierd alarm parameters. (See `parameters` syntax in `Assert` keyword reference)
        :param float timeout: Time to wait for alarm activation.
        :param string alias: Name of execution context.

        **EXAMPLE:**

        ::

            Assert alarm active    faultId=49, severity=Critical
        """
        timeout = timestr_to_secs(timeout)
        Or(IsString(), IsOneOf(None)).check(parameters)

        return self.store.get(alias).execute_infomodel_subscription("subscribeForActiveAlarms", {}, AnyObjectValidator(parameters), timeout)

    def assert_alarm_inactive(self, parameters=None, timeout=60, alias="default"):
        """Assert that there's no active alarm matching given parameters.

        :param string parameters: Requierd alarm parameters. (See `parameters` syntax in `Assert` keyword reference)
        :param float timeout: Time to wait for alarm deactivation.
        :param string alias: Name of execution context.
        """
        timeout = timestr_to_secs(timeout)
        Or(IsString(), IsOneOf(None)).check(parameters)

        return self.store.get(alias).execute_infomodel_subscription("subscribeForActiveAlarms", {}, NoneObjectsValidator(parameters), timeout)

    def _assert_no_unexpected_alarms(self, alarms):
        unexpected_alarms = list(filter(lambda a: not any(validator.check(
            a) for validator in self.allowed_alarm_validators), alarms))
        if unexpected_alarms:
            raise AdminApiProcedureFailureException(
                "Unexpected alarms:\n{}".format(unexpected_alarms))

    def assert_(self, class_name, id, parameters=None, timeout=10, alias="default"):
        """Assert that item exists and matches given parameters.

        :param string class_name: E.g. BTS, SMOD, BBU, RMOD, ALD, LNCEL, GNCEL or WNCEL
        :param string id: item ID
        :param string parameters: Requierd item parameters. None means no parameter value validation.
        :param float timeout: Time to wait for matching item.
        :param string alias: Name of execution context.

        |

        **PARAMETERS syntax:**
            - PARAMETER1 OPERATOR1 VALUE1, PARAMETER2 OPERATOR2 VALUE2, ...
                * examples: status=disabled, temperature>100, temperature<=120
                * single spaces between elements are allowed with one exception - see empty VALUE
            - PARAMETERs:
                * simple: temperature, status, etc.
                * nested: stateInfo.availabilityStatus, etc.
                * lists: alarms[5], stateInfo.reasoningStatus[?], alarms[*]
                    * \* means all elements
                    * ? means any element
            - OPERATORs: >, <, >=, <=, =, !=
            - VALUEs:
                * literal: 5, disabled
                * regex:
                    * positive match: parameter=regex"[Oo]nline"
                    * negative match: parameter!=regex"validated|onAirDone"
                * empty: string 'empty' is interpreted as an empty value, but there may be no space before it
                    * correct: parameter=empty, parameter !=empty
                    * incorrect: parameter = empty

        |

        **EXAMPLE:**

        ::

            Assert    RMOD    ${RMOD_ID}    productName=FXEA, ipAddress=192.168.253.204

        """ # noqa W605
        timeout = timestr_to_secs(timeout)

        IsString().check(class_name)
        IsString().check(id)
        Or(IsString(), IsOneOf(None)).check(parameters)

        return self.store.get(alias).execute_infomodel_subscription(
            "subscribeForParameters", {"className": class_name, "id": id}, ObjectValidator(parameters), timeout)

