    def get_active_alarms(self, severity=None, timeout=10, alias="default"):
        """
        Get active alarms.

        :param string severity: Alarm severity (critical, major, minor or warning)
        :param float timeout: Time to wait for positive procedure result.
        :param string alias: Name of execution context.

        :rtype: list
        :return: list of alarm objects

        """

        timeout = timestr_to_secs(timeout)
        IsOneOf("critical", "major", "minor", "warning", None).check(severity)

        return self._get_alarms("currentAlarms", severity, False, timeout, alias)

    def start_historical_alarm_tracker(self, timeout=10, alias="default"):
        """
        Start historical alarm tracker.
            Historical alarm is an alarm which was cleared during the period of tracking.
            If alarm was only 'set' it will not appear on Historical Alarms list

        :param float timeout: Time to wait for positive procedure result.
        :param string alias: Name of execution context.

        """
        timeout = timestr_to_secs(timeout)
        self.store.get(alias).execute_infomodel_request(
            "abnormalities", {"type": "startHistoricalTracker"}, timeout)

    def get_historical_alarms(self, severity=None, load_history=False, timeout=10, alias="default"):
        """
        Get historical alarms.

        :param string severity: Alarm severity (critical, major, minor or warning)
        :param boolean load_history: load entire BTS history (may significantly extent time for request)
        :param float timeout: Time to wait for positive procedure result.
        :param string alias: Name of execution context.

        :rtype: list
        :return: list of alarm objects

        """
        load_history = to_bool(load_history)
        timeout = timestr_to_secs(timeout)
        IsOneOf("critical", "major", "minor", "warning", None).check(severity)

        return self._get_alarms("historicalAlarms", severity, load_history, timeout, alias)

    @wrap_result
    def _get_alarms(self, alarm_type, severity, load_history, timeout, alias):

        parameters = {"type": alarm_type}
        if load_history:
            parameters["loadHistory"] = load_history
        if severity:
            parameters["severity"] = severity
        return self.store.get(alias).execute_infomodel_request("abnormalities", parameters, timeout)

    @classmethod
    def add_allowed_alarm(self, parameters, alias="default"):
        """
        Add allowed alarm.

        :param string parameters: Allowed alarm parameters. (See `parameters` syntax in `Assert` keyword reference)
        :param string alias: Name of execution context.

        """
        self.allowed_alarm_validators.append(ObjectValidator(parameters))

    @classmethod
    def clear_allowed_alarms_list(self, alias="default"):
        """
        Clear allowed alarms list.

        :param string alias: Name of execution context.

        """
        self.allowed_alarm_validators = []

    def assert_no_unexpected_active_alarms(self, alias="default"):
        """
        Assert no unexpected active alarms.

        :param string alias: Name of execution context.

        """

        self._assert_no_unexpected_alarms(self.get_active_alarms(alias=alias))

    def assert_no_unexpected_historical_alarms(self, load_history=False, alias="default"):
        """
        Assert no unexpected historical alarms.

        :param boolean load_history: load entire BTS history (may significantly extent time for request)
        :param string alias: Name of execution context.

        """

        load_history = to_bool(load_history)
        self._assert_no_unexpected_alarms(
            self.get_historical_alarms(load_history=load_history, alias=alias))
